import React from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { Shield, User, LogOut, Globe, ShieldAlert, FileSearch, Lock, Server } from 'lucide-react';

export default function Navbar({ user, onLogout }) {
  const navigate = useNavigate();
  const location = useLocation();

  const scrollToSection = (sectionId) => {
    if (location.pathname !== '/') {
      navigate('/');
      setTimeout(() => {
        const element = document.getElementById(sectionId);
        if (element) element.scrollIntoView({ behavior: 'smooth' });
      }, 150);
    } else {
      const element = document.getElementById(sectionId);
      if (element) element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <nav className="soc-navbar">
      <div 
        onClick={() => scrollToSection('hero-section')} 
        style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer' }}
      >
        <Shield size={26} color="var(--accent-cyan)" />
        <span className="hacker-glow" style={{ fontSize: '16px', fontWeight: 'bold', fontFamily: 'var(--font-mono)', color: 'var(--accent-cyan)' }}>
          NET_SENTINEL // SOC
        </span>
      </div>

      {/* Responsive Navigation Links with Visible White Text */}
      <div className="nav-links-container" style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
        
        <button onClick={() => scrollToSection('tool-host')} className="cyber-nav-btn">
          <Globe size={13} color="var(--accent-cyan)" /> HOST INTEL
        </button>

        <button onClick={() => scrollToSection('tool-port')} className="cyber-nav-btn">
          <ShieldAlert size={13} color="var(--alert-red)" /> PORT CVE
        </button>

        <button onClick={() => scrollToSection('tool-subdomain')} className="cyber-nav-btn">
          <FileSearch size={13} color="var(--warning-amber)" /> SUBDOMAINS
        </button>

        <button onClick={() => scrollToSection('tool-dir')} className="cyber-nav-btn">
          <Lock size={13} color="var(--accent-green)" /> DIR EXPOSURE
        </button>

        <button onClick={() => scrollToSection('tool-ssl')} className="cyber-nav-btn">
          <Server size={13} color="var(--accent-cyan)" /> SSL AUDIT
        </button>

        {user ? (
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginLeft: '6px' }}>
            <span style={{ fontFamily: 'var(--font-mono)', color: 'var(--accent-green)', fontSize: '11px' }}>
              [{user.name}]
            </span>
            <button className="cyber-nav-btn" onClick={() => { onLogout(); navigate('/'); }} style={{ padding: '6px 8px' }}>
              <LogOut size={13} />
            </button>
          </div>
        ) : (
          <Link to="/login" className="cyber-nav-btn" style={{ backgroundColor: 'rgba(0, 243, 255, 0.15)' }}>
            <User size={13} /> LOGIN
          </Link>
        )}
      </div>
    </nav>
  );
}
